"use client"

import { Star, Heart, ShoppingCart } from "lucide-react"
import Link from "next/link"
import { useCart } from "@/components/cart-provider"

interface Product {
    id: string | number
    name: string
    category: string
    price: number
    originalPrice?: number
    rating: number
    reviews: number
    image: string
    isNew?: boolean
}

interface ProductCardProps {
    product: Product
}

export default function ProductCard({ product }: ProductCardProps) {
    const { addItem } = useCart()

    const handleAddToCart = (e: React.MouseEvent) => {
        e.preventDefault() // Prevent navigation if wrapped in Link
        addItem({
            id: product.id.toString(),
            name: product.name,
            price: product.price,
            quantity: 1,
            image: product.image,
            category: product.category
        })
    }

    return (
        <div className="rounded-xl bg-card border border-border overflow-hidden hover:shadow-lg hover:border-primary transition group h-full flex flex-col relative">
            {/* Image Container */}
            <div className="relative bg-secondary p-8 h-48 flex items-center justify-center overflow-hidden">
                <div className="text-6xl group-hover:scale-110 transition flex items-center justify-center w-full h-full">
                    {product.image.startsWith('/') || product.image.startsWith('http') ? (
                        <img src={product.image} alt={product.name} className="max-h-full max-w-full object-contain" />
                    ) : (
                        <span className="text-6xl">{product.image}</span>
                    )}
                </div>

                {product.isNew && (
                    <span className="absolute top-3 left-3 bg-accent text-accent-foreground text-xs font-bold px-3 py-1 rounded-full">
                        New
                    </span>
                )}

                <button className="absolute top-3 right-3 p-2 bg-white rounded-full shadow hover:scale-110 transition opacity-0 group-hover:opacity-100 z-10">
                    <Heart className="w-4 h-4 text-accent" />
                </button>
            </div>

            {/* Product Details */}
            <div className="p-4 flex flex-col flex-grow">
                <div className="mb-auto">
                    <span className="text-xs font-medium text-primary bg-primary/10 px-2 py-1 rounded inline-block mb-3">
                        {product.category}
                    </span>

                    <Link href={`/products/${product.id}`} className="block hover:text-primary transition-colors">
                        <h3 className="font-semibold text-foreground text-sm mb-3 line-clamp-2 leading-tight">
                            {product.name}
                        </h3>
                    </Link>

                    {/* Rating */}
                    <div className="flex items-center gap-1 mb-3">
                        <div className="flex gap-0.5">
                            {[...Array(5)].map((_, i) => (
                                <Star
                                    key={i}
                                    className={`w-3.5 h-3.5 ${i < Math.floor(product.rating) ? "fill-accent text-accent" : "text-border"
                                        }`}
                                />
                            ))}
                        </div>
                        <span className="text-xs text-muted-foreground ml-1">({product.reviews})</span>
                    </div>

                    {/* Price */}
                    <div className="flex items-baseline gap-2 mb-4">
                        <span className="text-lg font-bold text-primary">₹{product.price}</span>
                        {product.originalPrice && (
                            <>
                                <span className="text-sm text-muted-foreground line-through">
                                    ₹{product.originalPrice}
                                </span>
                                <span className="text-xs font-semibold text-accent">
                                    {Math.round(
                                        ((product.originalPrice - product.price) / product.originalPrice) * 100,
                                    )}
                                    % OFF
                                </span>
                            </>
                        )}
                    </div>
                </div>

                {/* Actions */}
                <div className="flex gap-2 mt-2">
                    <button
                        onClick={handleAddToCart}
                        className="flex-1 bg-primary text-primary-foreground font-medium text-sm py-2 rounded-lg hover:opacity-90 transition flex items-center justify-center gap-2"
                    >
                        <ShoppingCart className="w-4 h-4" />
                        <span className="hidden sm:inline">Add</span>
                    </button>
                    <Link
                        href={`/products/${product.id}`}
                        className="flex-1 border border-primary text-primary font-medium text-sm py-2 rounded-lg hover:bg-primary hover:text-primary-foreground transition flex items-center justify-center"
                    >
                        Details
                    </Link>
                </div>
            </div>
        </div>
    )
}
